agc_status_t agc_dispatch_job(agc_job_ctx_t *ctx)
{
    if (!AGC_ASSERT(ctx != NULL))
    {
        return (AGC_STATUS_BAD_ARG);
    }

    if (!AGC_ASSERT(ctx->id > AGC_JOB_NONE && ctx->id < AGC_JOB_COUNT))
    {
        return (AGC_STATUS_BAD_ARG);
    }

    if (ctx->id < AGC_JOB_CHARIN)
    {
        return (job_exec_0(ctx));
    }

    if (ctx->id < AGC_JOB_ATTITUDE_MANEUVER_ENTER)
    {
        return (job_io(ctx));
    }

    if (ctx->id < AGC_JOB_STATEUP_STALL)
    {
        return (job_imu_0(ctx));
    }

    if (ctx->id < AGC_JOB_EXTERNAL_DELTA_V)
    {
        return (job_nav_0(ctx));
    }

    if (ctx->id < AGC_JOB_ALIGN_COARSE_DONE)
    {
        return (job_guidance_0(ctx));
    }

    if (ctx->id < AGC_JOB_ALFLT1)
    {
        return (job_programs(ctx));
    }

    if (ctx->id < AGC_JOB_AGS_INITIALIZATION)
    {
        return (job_csm(ctx));
    }

    return (job_lm(ctx));
}

agc_status_t agc_dispatch_task(agc_task_id_t task)
{
    if (!AGC_ASSERT(agc_interrupts_inhibited()))
    {
        return (AGC_STATUS_BAD_ARG);
    }

    if (!AGC_ASSERT(task > AGC_TASK_NONE && task < AGC_TASK_COUNT))
    {
        return (AGC_STATUS_BAD_ARG);
    }

    if (task < AGC_TASK_MONREQ)
    {
        return (task_exec_0(task));
    }

    if (task < AGC_TASK_8192AUG)
    {
        return (task_io_0(task));
    }

    if (task < AGC_TASK_STATEINT)
    {
        return (task_imu_0(task));
    }

    if (task < AGC_TASK_RENDEZVOUS_PARAMETER_DISPLAY)
    {
        return (task_nav_0(task));
    }

    if (task < AGC_TASK_ALLOOP1)
    {
        return (task_programs_0(task));
    }

    if (task < AGC_TASK_ENGOFF1)
    {
        return (task_csm(task));
    }

    return (task_lm(task));
}
